const AVATAR_DESIGN_COUNT=12*12*10*6;
// Legacy IDs 0..575 retain their exact older appearance. New IDs start at 576.
const unpackAvatar=n=>{const raw=Number(n);const id=Number.isSafeInteger(raw)&&raw>=0?raw:0;if(id<576)return {palette:id%8,shape:Math.floor(id/8)%4,accessory:Math.floor(id/32)%6,face:Math.floor(id/192)%3};let v=Math.min(AVATAR_DESIGN_COUNT-1,id-576);const palette=v%12;v=Math.floor(v/12);const shape=v%12;v=Math.floor(v/12);const accessory=v%10;v=Math.floor(v/10);return {palette,shape,accessory,face:v%6};};
const packAvatar=({palette,shape,accessory,face})=>576+Math.max(0,Math.min(11,Number(palette)||0))+12*(Math.max(0,Math.min(11,Number(shape)||0))+12*(Math.max(0,Math.min(9,Number(accessory)||0))+10*Math.max(0,Math.min(5,Number(face)||0))));
const PANIKO_GEAR=['','🧢','👑','🕶️','🪐','🎀','🎧','🌸','⚡','🧶'];
const panikoTag=(id)=>{const c=unpackAvatar(id);return PANIKO_SHAPES[c.shape]+ ' · '+PANIKO_PALETTES[c.palette]};

